# TELEGRAM BOT
# ============================================================

bot = Bot(BOT_TOKEN) if BOT_TOKEN else None
dp = Dispatcher()

@dp.message(CommandStart())
async def start_handler(message: Message):
    if not message.from_user:
        return

    uid = message.from_user.id
    was_new = db_one("SELECT id FROM users WHERE id=?", (uid,)) is None
    upsert_user(
        uid,
        message.from_user.username or "",
        message.from_user.first_name or ""
    )

    # Track /start ref_<telegram_id> once. This is referral attribution only;
    # it does not create a commission on gambling or wagers.
    parts = (message.text or "").split(maxsplit=1)
    if was_new and len(parts) == 2 and parts[1].startswith("ref_"):
        try:
            referrer_id = int(parts[1][4:])
            if referrer_id != uid and db_one("SELECT id FROM users WHERE id=?", (referrer_id,)):
                db_exec("INSERT OR IGNORE INTO referrals(user_id,referrer_id,created_at) VALUES(?,?,?)",
                        (uid, referrer_id, now()))
        except ValueError:
            pass

    text = (
        "<b>BEAR BOT</b>\n\n"
        "Добро пожаловать.\n"
        "Открой Mini App через кнопку ниже."
    )

    if WEBAPP_URL:
        from aiogram.types import InlineKeyboardMarkup, InlineKeyboardButton, WebAppInfo
        keyboard = InlineKeyboardMarkup(
            inline_keyboard=[
                [InlineKeyboardButton(
                    text="Открыть BEAR BOT",
                    web_app=WebAppInfo(url=WEBAPP_URL)
                )]
            ]
        )
        await message.answer(text, reply_markup=keyboard)
    else:
        await message.answer(
            text + "\n\nWEBAPP_URL пока не установлен в ENV."
        )

@dp.message(Command("id"))
async def id_handler(message: Message):
    if message.from_user:
        await message.answer(f"Ваш Telegram ID: <code>{message.from_user.id}</code>")

@dp.pre_checkout_query()
async def pre_checkout(query: PreCheckoutQuery):
    # Never blindly accept malformed payloads.
    payload = query.invoice_payload or ""
    if not payload.startswith("purchase:"):
        await query.answer(ok=False, error_message="Некорректный платёж.")
        return
    await query.answer(ok=True)

@dp.message(F.successful_payment)
async def successful_payment(message: Message):
    payment = message.successful_payment
    if not payment or not message.from_user:
        return

    uid = message.from_user.id
    payload = payment.invoice_payload

    # Idempotency: do not credit the same Telegram charge twice.
    existing = db_one(
        "SELECT id FROM payments WHERE telegram_charge_id=?",
        (payment.telegram_payment_charge_id,)
    )
    if existing:
        return

    try:
        _, payload_uid, stars, _nonce = payload.split(":", 3)
        payload_uid = int(payload_uid)
        stars = int(stars)
    except Exception:
        return

    if payload_uid != uid:
        return

    # Stars payment is recorded as a fixed digital purchase.
    # It is NOT converted into a gambling balance or internal coins.

    db_exec(
        "INSERT INTO payments(user_id,telegram_charge_id,payload,stars,status,created_at) "
        "VALUES(?,?,?,?,?,?)",
        (
            uid,
            payment.telegram_payment_charge_id,
            payload,
            stars,
            "paid",
            now()
        )
    )

    db_exec(
        "UPDATE users SET stars_spent=stars_spent+?, updated_at=? WHERE id=?",
        (stars, now(), uid)
    )

    db_exec(
        "INSERT INTO transactions(user_id,kind,amount,description,created_at) "
        "VALUES(?,?,?,?,?)",
        (uid, "stars_purchase", stars, f"Оплачено {stars} Telegram Stars", now())
    )

    await message.answer(
        f"Платёж принят.\n"
        f"⭐ Stars: {stars}\n"
        f"Это была фиксированная цифровая покупка; игровой баланс не начислялся."
    )

# ============================================================
# FASTAPI
# ============================================================

@asynccontextmanager
async def lifespan(app: FastAPI):
    if not BOT_TOKEN:
        print("WARNING: BOT_TOKEN is empty. Telegram bot is disabled.")
        yield
        return

    task = asyncio.create_task(dp.start_polling(bot))
    try:
        yield
    finally:
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass
        await bot.session.close()

app = FastAPI(title="BEAR BOT", lifespan=lifespan)

